"""Build the classroom component primer and illustrated installation guide."""
from pathlib import Path
import html,json,os
from release_links import release_downloads
REPO=Path(__file__).resolve().parents[2]
SITE=REPO/'docs/manual'
E=lambda v:html.escape(str(v),quote=True)

def rel(page,target):return os.path.relpath(SITE/target,page.parent).replace('\\','/')
def nav(page,section):
 links=[('home','Home','index.html'),('components','Components','components/index.html'),('learnings','Learnings','learnings/index.html'),('setup','Getting Started','getting-started/index.html')]
 return '<!-- MANUAL NAV START --><div class="manual-bar"><a class="manual-brand" href="'+rel(page,'index.html')+'">TOP OPT LAB <span>/ MANUAL</span></a><div class="manual-links" role="navigation" aria-label="Main manual navigation">'+''.join('<a '+('aria-current="page" ' if key==section else '')+'href="'+rel(page,target)+'">'+label+'</a>' for key,label,target in links)+'</div></div><!-- MANUAL NAV END -->'
CSS='''<style>.primer-toc{columns:2;column-gap:2rem}.primer-toc li{break-inside:avoid;margin:.5rem 0}.primer-component,.installation-step{scroll-margin-top:7rem;margin:3rem 0;padding-top:1.5rem;border-top:1px solid #d7dfdb}.primer-heading{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:2rem;align-items:start}.primer-photo{margin:0;text-align:center}.primer-photo img{max-width:100%;width:auto;max-height:440px;height:auto}.port-table{width:100%;border-collapse:collapse;margin:1rem 0;table-layout:fixed}.port-table th,.port-table td{padding:.7rem;border:1px solid #d7dfdb;text-align:left;vertical-align:top;overflow-wrap:anywhere}.port-table th{background:#e5eee9}.port-table th:first-child{width:15%}.port-table th:nth-child(2){width:28%}.port-table small{display:block;font-size:.84rem;color:#51696e;margin-top:.35rem}.port-table code{font-weight:700}.primer-note{padding:1rem 1.2rem;border-left:4px solid #b55a2d;background:#fff4e8}.install-figure{margin:1.5rem 0}.install-figure img{display:block;width:100%;height:auto;border:1px solid #d7dfdb}.installation-actions{display:flex;gap:.8rem;flex-wrap:wrap}.installation-actions code{overflow-wrap:anywhere}.primer-types td:first-child{font-weight:700}.primer-page details>summary{font-weight:700;cursor:pointer;margin:1rem 0}.primer-page code{overflow-wrap:anywhere}.installation-page pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:1rem;background:#e5eee9}@media(max-width:700px){.primer-toc{columns:1}.primer-heading{grid-template-columns:1fr}.primer-photo img{max-height:320px}.port-table{font-size:.88rem}.port-table th,.port-table td{padding:.45rem}.port-table th:first-child{width:18%}.port-table th:nth-child(2){width:30%}}</style>'''
def page(target,title,body,section,extra_class):
 p=SITE/target;p.parent.mkdir(parents=True,exist_ok=True)
 doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title)+' · TopOptLab Manual</title><link data-manual-style rel="stylesheet" href="'+rel(p,'assets/manual.css')+'">'+CSS+'</head><body>'+nav(p,section)+'<main class="manual-content '+extra_class+'">'+body+'<footer class="manual-page-footer">TopOptLab 0.4.0-dev · English classroom manual · <a href="'+rel(p,'LICENSE.txt')+'">License</a></footer></main></body></html>'
 p.write_text(doc,encoding='utf-8')

def primer():
 data=json.loads((SITE/'data/component-primer.json').read_text(encoding='utf-8'))
 components={c['class']:c for c in json.loads((SITE/'data/components.json').read_text(encoding='utf-8'))['components']}
 p=SITE/'learnings/component-primer/index.html'
 body='<p class="manual-kicker">BEFORE THE WORKED EXAMPLES</p><h1>The components and their ports.</h1><p class="manual-lead">Understand what each component does, what enters on the left and what comes out on the right before building the plate example.</p><div class="installation-actions"><a class="manual-button" href="'+rel(p,'getting-started/installation/index.html')+'">Illustrated installation</a><a class="manual-button secondary" href="'+rel(p,'components/index.html')+'">Full reference: all 33 components</a><a class="manual-button secondary" href="'+rel(p,'learnings/01-understand-the-problem/index.html')+'">Then begin the example</a></div>'
 body+='<aside class="manual-related"><strong>Classroom sequence</strong><p>Complete installation before class. Use the first 35 minutes, shared by Lessons 01–02, for a 20-minute component tour and 15 minutes of first practice. Use the detailed lesson steps as checkpoints within that opening block, then continue to Lessons 03–08. The complete course still totals three hours including the ten-minute break.</p></aside>'
 body+='<h2>Component, port and wire</h2><ul><li>A <strong>component</strong> performs one task.</li><li>An <strong>input port</strong> is a socket on its left. Its label is local to that component.</li><li>An <strong>output port</strong> is a socket on its right. Connect this output to a compatible input on the next component.</li><li>A <strong>wire</strong> carries data. Hover over a port to read its full name, data type and description.</li></ul><p>For example, Domain <code>G</code> is the grid output, while Support <code>G</code> expects the geometry used to select nodes. The same letter can mean different things on different components.</p>'
 types=[('Closed curve','Rectangle or Circle parameter','Boundary B, optional Holes H and Keep K on Domain'),('Number','Number Slider','Cell size h, thickness or force component'),('Integer','Whole-number slider','Mode, case index or field selection'),('Point','Construct Point with X/Y/Z','Support or Load geometry selection G'),('Vector','Vector XYZ','Total force F or gravity acceleration g'),('Boolean','Boolean Toggle or Button','Fix X/Y, Run, Stop, Reset or Preview'),('TopOptLab data','Upstream component output','Domain, supports, loads, load cases, material, settings and results')]
 body+='<h2>The data you supply</h2><div class="table-wrap"><table class="port-table primer-types"><tr><th>Data</th><th>Create it with</th><th>Typical use</th></tr>'+''.join('<tr><td>'+E(a)+'</td><td>'+E(b)+'</td><td>'+E(c)+'</td></tr>' for a,b,c in types)+'</table></div><p>Geometry chooses a location or region. A number controls a value. A point locates the force; a vector sets its direction and magnitude. Connect model and result data from the component outputs shown below.</p>'
 body+='<h2>Defaults and required connections</h2><p>A stored default is used when that input has no wire. Connect a slider or other control to override it. The table separates required data, optional data and defaults. Engineering requires its physical inputs before you press Run even though its interface can remain visible while they are missing.</p><p>Use a <strong>Button</strong> for Run so it sends a short pulse. Changing an input does not start a calculation automatically. Hold <strong>Shift</strong> when adding a second source wire to a list input such as Supports or Cases.</p><h2>Classroom components</h2><ol class="primer-toc">'+''.join('<li><a href="#'+E(c)+'">'+E(components[c]['name'])+'</a></li>' for c in data['core_order'])+'</ol>'
 for key in data['core_order']:
  c=components[key];t=data['teaching'][key]
  body+='<section class="primer-component" id="'+E(key)+'"><div class="primer-heading"><div><p class="manual-kicker">'+E(c['subcategory'])+'</p><h2>'+E(c['name'])+'</h2><p>'+E(t['purpose'])+'</p><p><a href="'+rel(p,'components/index.html')+'#'+E(key)+'">Full component reference and verified connections</a></p></div><figure class="primer-photo"><a href="'+rel(p,'assets/components/'+key+'.png')+'"><img loading="lazy" src="'+rel(p,'assets/components/'+key+'.png')+'" alt="Native Grasshopper capsule render of '+E(c['name'])+'"></a><figcaption>Native component rendering. Open it at full size to inspect the layout.</figcaption></figure></div>'
  body+='<h3>What you give it</h3><div class="table-wrap"><table class="port-table"><tr><th>Input</th><th>Expected data</th><th>Starting value or connection</th></tr>'
  for port in c['inputs']:
   extra=t['ports'].get(str(port['index']),{})
   defaults=port.get('default',[])
   req=extra.get('connection_requirement') or ('Connect before Run' if port.get('required_on_run') else ('Stored default' if defaults else ('Optional connection' if port.get('optional') else 'Required connection')))
   typed=extra.get('readable_type',port['type'])
   value=extra.get('classroom_value') or (('Default: '+', '.join(str(x) for x in defaults)) if defaults else ('Leave unconnected when unused' if port.get('optional') else 'Connect the matching upstream output'))
   body+='<tr><td><code>'+E(port['nickname'])+'</code><small>'+E(port['name'])+'</small></td><td>'+E(typed)+'<small>'+E('List of values' if port['access']=='list' else 'One item')+' · '+E(req)+'</small></td><td>'+E(value)+'<small>'+E(port['description'])+'</small></td></tr>'
  body+='</table></div><h3>What it returns</h3><div class="table-wrap"><table class="port-table"><tr><th>Output</th><th>Data</th><th>How you use it</th></tr>'
  for port in c['outputs']:
   extra=t['outputs'].get(str(port['index']),{})
   body+='<tr><td><code>'+E(port['nickname'])+'</code><small>'+E(port['name'])+'</small></td><td>'+E(extra.get('readable_type',port['type']))+'</td><td>'+E(port['description'])+'</td></tr>'
  body+='</table></div><p class="primer-note"><strong>Check before continuing:</strong> '+E(t['common_mistake'])+'</p></section>'
 body+='<section class="manual-section"><h2>Now build the example</h2><p>Begin with the reference plate and use the connection walkthrough as you add each wire. Keep the complete 33-component guide available for the advanced 3D tools and less-used controls.</p><div class="installation-actions"><a class="manual-button" href="'+rel(p,'learnings/01-understand-the-problem/index.html')+'">Begin Lesson 01</a><a class="manual-button secondary" href="'+rel(p,'learnings/connections/index.html')+'">Follow the connections</a></div></section>'
 page('learnings/component-primer/index.html','Component and port introduction',body,'learnings','primer-page')

def installation():
 data=json.loads((SITE/'data/installation-assets.json').read_text(encoding='utf-8'))
 assets={a['file']:a for a in data['assets']}
 p=SITE/'getting-started/installation/index.html'
 def image(name):
  if name not in assets:return ''
  a=assets[name];return '<figure class="install-figure"><a href="'+rel(p,'assets/installation/'+name)+'"><img loading="lazy" src="'+rel(p,'assets/installation/'+name)+'" alt="'+E(a['caption'])+'"></a><figcaption>'+E(a.get('display_caption',a['caption']))+'</figcaption></figure>'
 body='<p class="manual-kicker">PRE-CLASS / ILLUSTRATED INSTALLATION</p><h1>TopOptLab on your computer.</h1><p class="manual-lead">Follow the supplied classroom kit from extraction to the first Grasshopper check. Rhino 8 with a working licence is required for calculations. The complete HTML manual works offline without installing the solver.</p><p><a class="manual-button" href="../index.html">Getting Started and installer links</a></p><div class="manual-related"><strong>Windows and Mac</strong><p>The Windows classroom installer includes its CPU Python runtime. The Mac package is a pilot for macOS 15 or later on Apple Silicon or Intel, with native Python 3.13. Native Mac/Rhino acceptance remains pending.</p></div>'
 body+=release_downloads()+'<p>PowerPoint presentations are separate instructor material. Follow the illustrated HTML steps below.</p>'
 body+='<p class="primer-note"><strong>Archived offline classroom route:</strong> the screenshots below describe the prepared October ZIP kits, whose release is still a draft. Use the current Package Manager instructions above for public installation. The Mac alpha has not yet been tested inside Rhino/Grasshopper for Mac.</p><section class="installation-step" id="extract"><h2>1. Extract the matching ZIP</h2><ol><li>Choose Windows x64, Mac Apple Silicon or Mac Intel from the downloads above. On Mac, Apple menu &gt; About This Mac identifies the processor.</li><li>Extract the complete ZIP into a short, writable local folder near your home directory. Do not merge different platform packages.</li><li>Keep <code>START_HERE.html</code> and <code>software/</code> together in <code>TopOptLab_Students_2026-10-26</code>.</li></ol>'+image('01-extracted-kit.png')+'</section>'
 body+='<section class="installation-step" id="manual"><h2>2. Open the one English manual</h2><ol><li>Open the extracted folder and double-click <code>START_HERE.html</code>.</li><li>On that page, click <strong>Open the complete English manual</strong>.</li><li>Use <strong>Getting Started</strong> for installation, <strong>Learnings</strong> for the course and <strong>Components</strong> for the full input/output reference.</li></ol><p>If needed, open <code>software/source/TopOptLab-Rhino/docs/manual/index.html</code> directly in a browser. The manual works offline without Rhino or Python.</p>'+image('08-start-here.png')+image('02-manual-home.png')+'</section>'
 body+='<section class="installation-step" id="windows"><h2>3. Windows: close Rhino and launch setup</h2><ol><li>Save your work and close every Rhino window.</li><li>Open the kit folder <code>software/windows/</code> and run <code>TopOptLab-Students-Windows-0.4.0-Setup.exe</code>.</li><li>Follow the English installer instructions for your user account. The CPU runtime and numerical dependencies are included.</li></ol>'+image('03-windows-getting-started.png')+image('06-installer-native-render.png')+'<p>The interface image shows the initial installer controls. Continue on your own computer and read its actual completion or error message before reopening Rhino.</p>'+image('04-windows-installer-guide.png')+'</section>'
 body+='<section class="installation-step" id="mac"><h2>4. Mac: prepare the pilot and run its launcher</h2><ol><li>Use the matching Apple Silicon or Intel ZIP with macOS 15 or later and Rhino 8. Read <code>software/mac-pilot/README.html</code>.</li><li>Before closing Rhino, open Grasshopper &gt; File &gt; Special Folders &gt; Components Folder and note that folder location. Then save and close Rhino.</li><li>Keep <code>software/mac-pilot/</code> beside <code>software/source/</code>. Run <code>INSTALL_MAC_PILOT.command</code>. If it opens the included Python 3.13 installer, finish that installation and run the launcher again.</li><li>Select the noted Grasshopper 8 Components Folder. Native Python is required; do not run through Rosetta. Each ZIP includes only its matching native wheel set.</li><li>Reopen Rhino and Grasshopper, then check a small 2D example. Complete a teacher test on a real Mac before relying on it for class calculations.</li></ol>'+image('05-mac-pilot-guide.png')+image('07-mac-installation-steps.png')+'<p class="primer-note">These images show the Apple Silicon edition of the supplied pilot guide in a browser. They do not show a completed native Mac installation. Earlier macOS versions are outside the bundled dependency coverage.</p></section>'
 body+='<section class="installation-step" id="check"><h2>5. Reopen Rhino and check the components</h2><ol><li>Start Rhino 8 and run Grasshopper.</li><li>Find the <strong>TopOptLab</strong> tab and place <strong>TopOpt Domain</strong>.</li><li>Use the <a href="'+rel(p,'learnings/component-primer/index.html')+'">component primer</a> before building the example.</li><li>In the first plate exercise, connect the closed rectangle to B and h = 6 mm to lowercase h. Confirm 200 cells and use Display &gt; Preview Mesh Edges to show the grid.</li></ol><figure class="primer-photo"><img src="'+rel(p,'assets/components/DomainComponent.png')+'" alt="Native rendering of the TopOpt Domain component with B H K h P inputs and D G K outputs"><figcaption>Native rendering of the component to find in Grasshopper.</figcaption></figure><p>Keep the installed runtime in place because the plugin starts an external Python worker. Read any runtime message and the Engineering Status panel when a check fails.</p><p><a class="manual-button" href="'+rel(p,'learnings/component-primer/index.html')+'">Continue to components and ports</a></p></section>'
 page('getting-started/installation/index.html','Illustrated installation',body,'setup','installation-page')

if __name__=='__main__':
 primer();installation();print('Built the classroom component primer and illustrated installation guide.')
